99	 * case on a fresh login, where the user has Spotify open somewhere but hasn't
100	 * pressed play. Rather than surfacing that as an error, look for a reachable
101	 * device and aim at it explicitly.
102	 *
103	 * Only `play` gets this treatment: pause/next against no device are genuinely
104	 * meaningless, and waking a client to immediately pause it would be surprising.
105	 */
106	export async function play(token, { contextUri, deviceId } = {}) {
107	  const body = contextUri ? { context_uri: contextUri } : undefined;
108	  try {
109	    return await playerCommand("PUT", "play", token, body, deviceId);
110	  } catch (err) {
111	    // An explicit deviceId that 404s is a dead device, not a missing one —
112	    // re-resolving would just pick the same list and loop.
113	    if (err.message !== "NO_ACTIVE_DEVICE" || deviceId) throw err;
114	
115	    const device = pickPlaybackDevice(await fetchDevices(token));
116	    // Nothing open anywhere. No API call can fix this; the user has to open
117	    // Spotify, so let NO_ACTIVE_DEVICE through with its original meaning.
118	    if (!device) throw err;
119	    return playerCommand("PUT", "play", token, body, device.id);
120	  }
