125	export async function fetchFollowedArtists(token) {
126	  const artists = [];
127	  let after;
128	  do {
129	    const url = new URL("https://api.spotify.com/v1/me/following");
130	    url.searchParams.set("type", "artist");
131	    url.searchParams.set("limit", "50");
132	    if (after) url.searchParams.set("after", after);
133	    const response = await fetch(url, {
134	      headers: { Authorization: `Bearer ${token}` },
135	    });
136	    const err = spotifyError(response);
137	    if (err) throw err;
138	    const data = await response.json();
139	    for (const a of data.artists.items) {
140	      artists.push({
141	        id: a.id,
142	        name: a.name,
143	        imageUrl: a.images[0]?.url ?? null,
144	      });
145	    }
146	    after = data.artists.cursors.after ?? null;
147	  } while (after);
148	  return artists;
149	}
